                if c > 180.0 { c -= 360.0; }
                let fw = 1.0 - c.abs() / 220.0;
                let score = depth * (cnt as f64).powf(0.7) * (0.4 + fw);
                if score > best_score { best_score = score; best_center = c; best_depth = depth; }
                k = j;
            } else { k += 1; }
