        let d3 = rp("d3"); let d11 = pf(&rp("d11"));
        if d3.contains("goal=1") || d3.contains("here=1") {
            goal_seen += 1;
            let _ = writeln!(log, "t={} !!!FLAGS {} d11={:.2} xy={:.0};{:.0} hdg={:.1}", t0.elapsed().as_secs(), d3, d11, x, y, heading);
            let _ = log.flush();
