        let d0 = avg_d11(8);
        if d0 > best { best = d0; }
        // drive forward 2.5s
        let end = Instant::now() + Duration::from_millis(2500);
        while Instant::now() < end { wp("d1", 1.1); wp("d7", 1.1); std::thread::sleep(Duration::from_millis(50)); }
        wp("d1", 0.0); wp("d7", 0.0);
        std::thread::sleep(Duration::from_millis(300));
        let d1 = avg_d11(8);
        let delta = d1 - d0;
