            wp("d1", 0.0); wp("d7", 0.0);
        }
        let d3 = rp("d3");
        let _ = writeln!(log, "t={} d0={:.3} d1={:.3} delta={:+.3} best={:.3} {} {}",
            t0.elapsed().as_secs(), d0, d1, delta, best, action, d3);
        let _ = log.flush();
